          "kind": "result",
          "claim_status": "observed",
          "source_origin": "research_note",
          "conditions": ["eps = 1e-06", "MODE: HYBRID (matmul=GPU, rest=CPU)", "Output Dimension: 16"],
          "observations": ["calc success"],
          "parameters": [],
